python3 - <<'PY'
import json
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:8125"


def get_json(path):
    url = BASE + path
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            status = response.status
            body = response.read()
    except Exception as exc:
        raise RuntimeError(f"GET {url} failed: {exc}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"GET {url} returned HTTP {status}: {body.decode('utf-8', 'replace')}")
    try:
        return json.loads(body)
    except Exception as exc:
        raise RuntimeError(f"GET {url} returned invalid JSON: {exc}") from exc

try:
    last = get_json("/batches/last")
    last_seq = last["last_seq"]
    if isinstance(last_seq, bool) or not isinstance(last_seq, int):
        raise RuntimeError("GET /batches/last JSON field 'last_seq' is not an integer")

    page = get_json("/orders?" + urllib.parse.urlencode({"after": last_seq}))
    orders = page["orders"] if isinstance(page, dict) and "orders" in page else page
    if not isinstance(orders, list):
        raise RuntimeError("GET /orders response does not contain an orders list")

    if orders:
        seqs = []
        order_count = len(orders)
        total_units = 0
        total_revenue_cents = 0
        revenue_by_region_cents = {}

        for i, order in enumerate(orders):
            if not isinstance(order, dict):
                raise RuntimeError(f"Order at index {i} is not an object")
            try:
                seq = order["seq"]
                units = order["units"]
                price = order["unit_price_cents"]
                region = order["region"]
            except KeyError as exc:
                raise RuntimeError(f"Order at index {i} lacks field {exc.args[0]!r}") from exc
            for name, value in (("seq", seq), ("units", units), ("unit_price_cents", price)):
                if isinstance(value, bool) or not isinstance(value, int):
                    raise RuntimeError(f"Order at index {i} field {name!r} is not an integer")
            if not isinstance(region, str):
                raise RuntimeError(f"Order at index {i} field 'region' is not a string")
            revenue = units * price
            seqs.append(seq)
            total_units += units
            total_revenue_cents += revenue
            revenue_by_region_cents[region] = revenue_by_region_cents.get(region, 0) + revenue

        batch = {
            "batch_start_seq": min(seqs),
            "batch_end_seq": max(seqs),
            "order_count": order_count,
            "total_units": total_units,
            "total_revenue_cents": total_revenue_cents,
            "revenue_by_region_cents": revenue_by_region_cents,
        }
        data = json.dumps(batch, separators=(",", ":")).encode("utf-8")
        request = urllib.request.Request(
            BASE + "/batches",
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                status = response.status
                body = response.read()
        except urllib.error.HTTPError as exc:
            body = exc.read()
            raise RuntimeError(f"POST {BASE}/batches returned HTTP {exc.code}: {body.decode('utf-8', 'replace')}") from exc
        except Exception as exc:
            raise RuntimeError(f"POST {BASE}/batches failed: {exc}") from exc
        if not 200 <= status < 300:
            raise RuntimeError(f"POST {BASE}/batches returned HTTP {status}: {body.decode('utf-8', 'replace')}")
except Exception as exc:
    raise SystemExit(f"Order batch processing failed: {exc}")
PY
